				+ "From: " + TestId1Data.FreemailAccount.ADDRESS_WITH_ANGLE + "\r\n"
				+ "Subject: Freemail SMTP test\r\n"
				+ "To: " + TestId1Data.FreemailAccount.ADDRESS_WITH_ANGLE + "\r\n"
				+ "\r\n"
				+ "This is a simple SMTP test for Freemail\r\n"
				+ "..\r\n";

